package habitTracker.KPI;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * A RUNNER collector as generated by the runner "kpi" job (kpi-sensors.md "Collector bundle"):
 * manifest {schedule, window, sources, unit, aggregation} + files {"collector.py", "fixtures/<case>/inputs/...",
 * "fixtures/<case>/expected.json"}. Stored on the capability as one JSON string (toJson / fromJson).
 * Untrusted LLM output: CollectorStaticCheck validates it before it is sent anywhere.
 */
public record CollectorBundle(ObjectNode manifest, Map<String, String> files, String combineWhy) {

    /** Without the model's one-sentence reason for the combine rule. */
    public CollectorBundle(ObjectNode manifest, Map<String, String> files) {
        this(manifest, files, null);
    }

    private static final ObjectMapper JSON = new ObjectMapper();

    public String collectorPy() {
        return files.get("collector.py");
    }

    public String toJson() {
        ObjectNode n = JSON.createObjectNode();
        n.set("manifest", manifest);
        if (combineWhy != null && !combineWhy.isBlank()) n.put("combineWhy", combineWhy);
        ObjectNode f = n.putObject("files");
        files.forEach(f::put);
        return n.toString();
    }

    /** null for null/blank/unparseable (never throws: a stored bundle is display data). */
    public static CollectorBundle fromJson(String s) {
        if (s == null || s.isBlank()) return null;
        try {
            return of(JSON.readTree(s));
        } catch (Exception e) {
            return null;
        }
    }

    /** {manifest: object, files: {path: string|json}} → bundle; IllegalArgumentException when the shape is wrong. */
    public static CollectorBundle of(JsonNode n) {
        if (n == null || !n.isObject()) throw new IllegalArgumentException("not a JSON object");
        JsonNode m = n.get("manifest");
        if (m == null || !m.isObject()) throw new IllegalArgumentException("missing 'manifest' object");
        JsonNode f = n.get("files");
        if (f == null || !f.isObject()) throw new IllegalArgumentException("missing 'files' object");
        Map<String, String> files = new LinkedHashMap<>();
        f.fields().forEachRemaining(e -> {
            JsonNode v = e.getValue();
            // models sometimes inline fixture JSON as an object instead of a string: keep its text
            files.put(e.getKey(), v.isTextual() ? v.asText() : v.toString());
        });
        String why = n.path("combineWhy").isTextual() ? n.get("combineWhy").asText().strip() : null;
        return new CollectorBundle(((ObjectNode) m).deepCopy(), files, why == null || why.isEmpty() ? null : why);
    }

    /** Distinct fixture case names, in file order. */
    public List<String> fixtureCases() {
        List<String> out = new ArrayList<>();
        for (String p : files.keySet()) {
            if (!p.startsWith("fixtures/")) continue;
            String[] parts = p.split("/", 3);
            if (parts.length >= 2 && !out.contains(parts[1])) out.add(parts[1]);
        }
        return out;
    }

    /** Source types declared in the manifest ("activitywatch", "file"), in order, deduped (union over variants). */
    public List<String> sourceTypes() {
        List<String> out = new ArrayList<>();
        collectTypes(manifest.get("sources"), out);
        variants().values().forEach(v -> collectTypes(v.get("sources"), out));
        return out;
    }

    private static void collectTypes(JsonNode sources, List<String> out) {
        if (sources != null && sources.isArray()) {
            sources.forEach(src -> {
                String t = src.path("type").asText("");
                if (!t.isEmpty() && !out.contains(t)) out.add(t);
            });
        }
    }

    // ── multi-device variants (kpi-multidevice.md "Hub bundle manifest") ──────

    /** OS key (Go runtime.GOOS) → variant {requires, sources}; empty for a legacy bundle. */
    public Map<String, JsonNode> variants() {
        Map<String, JsonNode> out = new LinkedHashMap<>();
        JsonNode v = manifest.get("variants");
        if (v != null && v.isObject()) v.fields().forEachRemaining(e -> out.put(e.getKey(), e.getValue()));
        return out;
    }

    /** Legacy = top-level sources, no variants: one variant for the OS of the device it was installed on. */
    public boolean isLegacy() {
        return !manifest.path("variants").isObject();
    }

    /** Cross-device rule from the manifest; "sum" when absent. */
    public String combine() {
        return manifest.path("combine").asText("sum");
    }

    /**
     * The manifest the hub sends ONE runner (POST /v1/collectors): {schedule, window, unit, aggregation, requires,
     * sources} from that OS's variant; combine/variants never reach the runner. A legacy bundle is its own single
     * variant, so any os resolves to the manifest as stored (minus combine). IllegalArgumentException when a
     * variants bundle has no entry for os (null included).
     */
    public ObjectNode resolve(String os) {
        ObjectNode out = manifest.deepCopy();
        out.remove("combine");
        if (isLegacy()) return out;
        JsonNode v = os == null ? null : manifest.path("variants").get(os);
        if (v == null || !v.isObject()) {
            throw new IllegalArgumentException("This collector has no variant for " + (os == null ? "an unknown OS" : os));
        }
        out.remove("variants");
        out.remove("sources");
        out.remove("requires");
        v.fields().forEachRemaining(e -> out.set(e.getKey(), e.getValue().deepCopy()));
        return out;
    }

    /** A legacy bundle rewritten as a variants bundle whose single variant is `os` (top-level sources/requires move into it). */
    public CollectorBundle withVariantFor(String os, String combine) {
        if (!isLegacy()) return this;
        ObjectNode m = manifest.deepCopy();
        ObjectNode variant = JSON.createObjectNode();
        if (m.has("requires")) variant.set("requires", m.remove("requires"));
        variant.set("sources", m.has("sources") ? m.remove("sources") : JSON.createArrayNode());
        m.put("combine", combine == null || combine.isBlank() ? "sum" : combine);
        m.putObject("variants").set(os, variant);
        return new CollectorBundle(m, files, combineWhy);
    }
}
